from __future__ import annotations

import time
import threading
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, Hashable, TypeVar

T = TypeVar("T")
F = TypeVar("F", bound=Callable[..., Any])


class LRUCache:
    """Thread-safe LRU cache with per-entry TTL expiry."""

    def __init__(self, maxsize: int = 128, ttl: float = 60.0) -> None:
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.maxsize = maxsize
        self.ttl = ttl
        self._data: OrderedDict[Hashable, tuple[Any, float]] = OrderedDict()
        self._lock = threading.RLock()

    def _expired(self, expires_at: float) -> bool:
        return time.monotonic() >= expires_at

    def get(self, key: Hashable) -> Any | None:
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            value, expires_at = item
            if self._expired(expires_at):
                self._data.pop(key, None)
                return None
            self._data.move_to_end(key)
            return value

    def set(self, key: Hashable, value: Any) -> None:
        with self._lock:
            self._data[key] = (value, time.monotonic() + self.ttl)
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            self._purge_expired()
            return len(self._data)

    def _purge_expired(self) -> None:
        expired = [k for k, (_, exp) in self._data.items() if self._expired(exp)]
        for k in expired:
            self._data.pop(k, None)


def cache(maxsize: int = 128, ttl: float = 60.0) -> Callable[[F], F]:
    """Decorator caching function results by arguments with LRU eviction and TTL."""

    def decorator(func: F) -> F:
        store = LRUCache(maxsize=maxsize, ttl=ttl)

        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = (args, tuple(sorted(kwargs.items())))
            cached = store.get(key)
            if cached is not None:
                return cached
            result = func(*args, **kwargs)
            store.set(key, result)
            return result

        wrapper.cache_clear = store.clear  # type: ignore[attr-defined]
        return wrapper  # type: ignore[return-value]

    return decorator
